insert into public.edital_programas (edital_catalog_id, subject_catalog_id, texto, fonte_url, conferido_em)
select e.id, s.id, v.texto, 'https://conhecimento.fgv.br/sites/default/files/concursos/59_juiz_edital_abertura_consolidado_13-01-2026.pdf', '2026-08-03'
from (values
  ('Direito Civil', '1. Lei de Introdução às Normas do Direito Brasileiro; Aplicação da Lei no Tempo e no Espaço. Interpretação e Integração da Lei. Analogia. Princípios Gerais do Direito e Equidade. Usos e Costumes. 2. Das pessoas. Das pessoas naturais. Das pessoas jurídicas. Desconsideração da Personalidade Jurídica. Do domicílio. 3. Ausência. Direitos da Personalidade. 4. Dos bens. Dos bens divisíveis e indivisíveis. Dos bens considerados em si mesmo. Dos bens fungíveis e infungíveis. Dos bens reciprocamente considerados. Dos bens públicos. Do bem de família. 5. Dos fatos jurídicos. Do negócio jurídico. Dos defeitos dos negócios jurídicos. Das nulidades. Dos atos jurídicos lícitos. Dos atos ilícitos. Da prescrição e da decadência. Da prova. 6. Do direito das obrigações. Das modalidades das obrigações. Da transmissão das obrigações. Do adimplemento e extinção das obrigações. Do inadimplemento das obrigações. Mora, cláusula penal, perdas e danos. 7. Dos contratos em geral. Formação e extinção. Vícios redibitórios e evicção. Das várias espécies de contrato. Dos atos unilaterais. 8. Dos títulos de crédito. 9. Da responsabilidade civil em geral. Responsabilidade subjetiva e objetiva. Abuso do direito. 10. Das preferências e privilégios creditórios. 11. Do direito das coisas. 12. Da posse: aquisição, efeitos, perda. Os interditos possessórios. Usucapião. 13. Dos direitos reais. Da propriedade. Do condomínio. Da superfície. Das servidões. Do usufruto. Do uso. Da habitação. Do direito do promitente comprador. Do penhor, da hipoteca e da anticrese. Alienação fiduciária. 14. Do direito de família. Casamento. Do direito pessoal. Do direito patrimonial. Regime de bens. Da união estável. Da tutela e da curatela. Adoção. Poder familiar. Alimentos. 15. Do direito das sucessões. Da sucessão em geral. Da sucessão legítima. Da sucessão testamentária. Do inventário e da partilha. 16. Das disposições finais e transitórias do Código Civil Brasileiro, artigos 2.028 a 2.046. 17. Legislação Especial: Registros públicos (Lei nº 6.015/1973). Da alienação fiduciária (Decreto-Lei nº 911/1969). Lei nº 9.514/1997. Do condomínio em edificações e as incorporações imobiliárias (Lei nº 4.591/1964), Lei nº 10.931/2004. Do Estatuto do Idoso (Lei nº 10.741/2003). Da locação de imóveis urbanos (Lei nº 8.245/1991). Código de Defesa do Consumidor (Lei nº 8.078/1990). Estatuto da Pessoa com Deficiência (Lei nº 13.146/2015). Lei nº 14.382/2022. Lei de Liberdade Econômica (Lei nº 13.874/2019). Regime Jurídico Emergencial e Transitório das relações jurídicas de Direito Privado (Lei nº 14.010/2020). Resolução CNJ nº 452, de 22/4/2022. Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018).'),
  ('Direito Processual Civil', '1. Direito material e direito processual. Normas processuais fundamentais. Boa-fé, eficiência e colaboração processual. Direito processual e Constituição. Acesso à Justiça. Lesão e ameaça a direito. Instrumentalidade, efetividade, adequação, tempestividade e eficiência da tutela jurisdicional. Princípio da economia processual. Garantia da duração razoável do processo. Meios adequados de resolução de conflitos. Conciliação e mediação. Arbitragem. Aplicação das normas processuais. 2. Jurisdição e competência. Conceito. Características. Espécies. Escopos. Critérios. Limites. Princípios. Cooperação internacional. Incompetência absoluta e relativa. Meios de Suscitação. Modificação de competência. Prevenção. Prorrogação. Perpetuação. Cooperação nacional. Atos de concertação. Produção de prova única nos litígios em massa. Ação: conceito, natureza jurídica, teorias, condições, identificação e classificação. 3. Processo: conceito, natureza jurídica, teorias. Princípios. Pressupostos processuais. Sujeitos do processo. Partes e capacidade processual. Deveres processuais e responsabilidade. Litigância de má-fé e atos atentatórios à dignidade da justiça. Despesas processuais, honorários de sucumbência, multas e gratuidade da justiça. 4. Sucessão e substituição. Curador especial. Procuradores. Litisconsórcio: modalidades, poderes e limitação. Intervenção de terceiros: espécies, características. Assistência simples e litisconsorcial. Denunciação da lide. Chamamento ao processo. Incidente de desconsideração da personalidade jurídica. Amicus Curiae. Juiz: poderes, deveres e responsabilidades. Impedimento e suspeição. Auxiliares da Justiça. Carreiras essenciais à administração da Justiça. Ministério Público. Advocacia Pública. Defensoria Pública. 5. Atos processuais: conceito, classificação, forma. Prática de atos processuais no processo eletrônico. Atos das partes. Preclusão temporal, lógica e consumativa. Atos do juiz. Preclusão pro judicato. Tempo, lugar e comunicação dos atos processuais. Prazos. Citações e intimações. Teoria da aparência. Citação real e ficta. Contumácia. Invalidades processuais. Mera irregularidade. Anulabilidade. Nulidade. Vícios processuais sanáveis e insanáveis. Distribuição e registro. Valor da causa. 6. Negócio jurídico processual e convenção processual. Calendário processual. 7. Tutelas provisórias. Aspectos gerais. Poder geral de tutela. Tutelas de urgência. Tutela cautelar e tutela antecipada: cabimento, fungibilidade, momento, requisitos, procedimentalização. Estabilização da tutela antecipada requerida em caráter antecedente. Modalidades de tutela urgente antecipada na forma específica: tutela inibitória e tutela de remoção do ilícito. Tutela de evidência: cabimento, requisitos, procedimentalização. Distribuição do tempo do processo. 8. Procedimento comum. Formação, suspensão e extinção do Processo. Elementos da demanda. Petição inicial. Elementos. Do pedido: espécies, modificação, cumulação. Causa de pedir. Valor da causa. Impugnação. Dos documentos necessários à propositura da ação. Exame da petição inicial. Do indeferimento liminar da petição inicial. Do recurso cabível e seu procedimento. Do julgamento liminar de improcedência. Do recurso cabível e seu procedimento. Da decretação de prescrição e decadência. Emenda da inicial. Improcedência liminar do pedido. Audiência de conciliação ou de mediação. Resposta: conceito, espécies. Contestação. Reconvenção. Revelia. Providências preliminares e do saneamento. Julgamento conforme o estado do processo. Extinção do processo. Julgamento antecipado do mérito. Julgamento antecipado parcial do mérito. Saneamento e organização do processo. 9. Provas: conceito e disposições gerais. Relevância e admissibilidade. Prova direta e indireta. Presunções e máximas de experiência. Ônus e dever probatório. Distribuição estática e distribuição dinâmica. Inversão. Poderes probatórios do juiz. Prova ilícita. Regras de exclusão e regras de privilégio. Provas típicas e atípicas. Prova estatística nas demandas coletivas. Prova e tutela inibitória. Provas em espécie. Valoração da prova. Sistema do convencimento motivado. 10. Audiência de instrução e julgamento. Sentença. Conteúdo. Defeitos das sentenças. Reexame necessário. Coisa julgada. Limites subjetivos e objetivos. Relativização da coisa julgada. Julgamento liminar de improcedência. Liquidação de sentença. 11. Cumprimento de sentença provisório e definitivo. Cumprimento de Sentença: disposições gerais. Cumprimento de sentença que reconheça a exigibilidade de obrigação: (a) de pagar quantia certa; (b) de prestar alimentos, provisórios ou definitivos; (c) de pagar quantia certa pela Fazenda Pública; (d) de fazer, de não fazer e de entregar coisa. Defesa. 12. Procedimentos Especiais. Procedimentos de jurisdição voluntária. Procedimentos especiais de jurisdição contenciosa. 13. Processo de execução: princípios, disposições gerais, partes, competência, requisitos. Títulos executivos. Responsabilidade patrimonial. Espécies de execução. Execução para entrega de coisa. Execução das obrigações de fazer e não fazer. Execução por quantia certa. Execução contra a Fazenda Pública. Execução de alimentos. Embargos à execução. Suspensão e extinção do processo de execução. 14. Da ordem dos processos nos Tribunais e competência originária: disposições gerais. Técnica de julgamento não unânime. Incidentes de assunção de competência, de arguição de inconstitucionalidade e de resolução de demandas repetitivas. Conflito de competência. Homologação de sentença estrangeira e concessão de exequatur a carta rogatória. Ação rescisória. Reclamação. 15. Recursos: conceito, natureza jurídica, classificação, normas fundamentais, efeitos. Juízo de admissibilidade e juízo de mérito. Recursos em espécie: apelação, agravo de instrumento, embargos de declaração, agravo interno, recurso ordinário, recurso especial, recurso extraordinário. Repercussão geral em recurso extraordinário. Recursos extraordinário e especial repetitivos e seu julgamento. Agravo em recurso especial e em recurso extraordinário. Embargos de divergência. Código de Processo Civil (Lei nº 16.105/2015 e suas alterações). Sucedâneos recursais. Ações autônomas de impugnação. 16. Precedentes (ratio decidendi, obiter dictum, formação, vinculação, distinção e superação). Súmulas. Súmulas vinculantes. Papel das Cortes Superiores. 17. Procedimentos especiais previstos na legislação extravagante. Doutrina processual e legislação processual esparsa e suas alterações (independentemente de indicação específica do diploma legal, mas notadamente a respeito do indicado) sobre: bem de família (Lei nº 8.009/1990 e suas alterações); prescrição das ações contra a Fazenda Pública (Decreto nº 20.910/1932 e Decreto-Lei nº 4.597/1942); assistência judiciária (Lei nº 1.060/1950 e suas alterações); execução fiscal (Lei nº 6.830/1980 e suas alterações); divórcio, separação e união estável (Lei nº 6.515/1977 e suas alterações e Lei nº 9.278/1996); proteção do consumidor (Lei nº 8.078/1990) e suas alterações; desapropriação (Decreto-Lei nº 3.365/1941 e suas alterações); registros públicos (Lei nº 6.015/1973 e suas alterações); mandado de segurança (Lei nº 12.016/2009); ação popular e ação civil pública (Lei nº 4.717/1965 e suas alterações, Lei nº 7.347/1985 e suas alterações e Lei nº 8.429/1992 e Lei nº 14.230/2021); habeas data (Lei nº 9.507/1997); alimentos (Lei nº 5.478/1968 e suas alterações e Lei nº 11.804/2008); investigação de paternidade (Lei nº 8.560/1992 e suas alterações); habeas corpus cível; usucapião; Juizados Especiais Estadual e Federal (Lei nº 9.099/1995 e suas alterações e Lei nº 10.259/2001 e suas alterações) e Juizado Especial da Fazenda Pública (Lei nº 12.153/2009); informatização do processo judicial (Lei nº 11.419/2006); medidas cautelares e tutela antecipada contra o Poder Público/Fazenda Pública e suspensão de liminares (Lei nº 8.437/1992 e suas alterações e Lei nº 9.494/1997 e suas alterações); edição, revisão e cancelamento de enunciado de súmula vinculante pelo Supremo Tribunal Federal (Lei nº 11.417/2006); mediação e autocomposição de conflitos (Lei nº 13.140/2015). 18. Conceito de litígio coletivo. Processo coletivo. Litígios estruturais. Processos estruturais. Objeções aos processos estruturais. Técnicas para condução de processo judicial estrutural. Decisão e implementação de medidas estruturais.'),
  ('Direito do Consumidor', '1. Do Código de Defesa do Consumidor. Dos direitos do consumidor. Das disposições gerais. Dos direitos básicos do consumidor. 2. Da qualidade de produtos e serviços. Da preservação e da reparação de danos (da proteção à saúde e segurança). 3. Da responsabilidade pelo fato do produto e do serviço. Da responsabilidade por vício do produto e do serviço. 4. Da decadência e da prescrição. 5. Da desconsideração da personalidade jurídica. 6. Das práticas comerciais (das disposições gerais). Da oferta. Da publicidade. Das práticas abusivas. Da cobrança de dívidas. 7. Da proteção contratual: disposições gerais. Das cláusulas abusivas. Dos contratos de adesão. 8. Da defesa do consumidor em juízo. Das disposições do Código de Defesa do Consumidor relacionadas à defesa do consumidor em juízo. 9. Das ações coletivas para a defesa de interesses individuais homogêneos. 10. Das ações de responsabilidade do fornecedor de produtos e serviços. 11. Da tutela específica nas obrigações de fazer ou não fazer. 12. Da sentença. Da coisa julgada. Da liquidação da sentença coletiva. 13. Do cumprimento da sentença. Noção de verossimilhança e hipossuficiência para facilitação da defesa em juízo dos direitos do consumidor, inclusive com a inversão do ônus da prova. 14. Sanções administrativas e penais: Da competência concorrente, multa, apreensão, inutilização, cassação de registro, proibição de fabricação, suspensão temporária de atividade, revogação ou cassação de concessão ou permissão, da interdição. Da Contrapropaganda. 15. O sistema nacional de defesa do consumidor: A política nacional de relações de consumo ­ SNDC e PROCON. 16. Interesses difusos e coletivos: Origem histórica e evolução. 17. Tutela Jurisdicional dos Direitos e Interesses Difusos e Coletivos. 18. Interesse público e interesse privado. Interesse primário e interesse secundário. Interesses difusos. Interesses coletivos. Interesses individuais homogêneos. Interesses transindividuais e sua tutela coletiva. 19. A tutela em juízo dos interesses individuais homogêneos, difusos e coletivos. Competência. 20. Legitimação: ordinária e extraordinária. Legitimação ativa e legitimação passiva. Litisconsórcio e assistência. 21. Conexão, continência e litispendência. Liminares e recursos. A imposição de multas. 22. Fundo para reconstituição do bem lesado: fundos federais, fundos estaduais, receitas do fundo, finalidades do fundo, a reparação das lesões individuais. 23. Sentença. Desistência e renúncia do recurso. Efeitos. Desistência pelo Ministério Público. Oitiva do Conselho Superior do Ministério Público. 24. Coisa julgada na ação coletiva. A coisa julgada coletiva e as ações individuais. Responsabilidade pelas custas, honorários advocatícios e demais encargos da sucumbência. 25. Liquidação da sentença. Legitimados para a liquidação. Escolha do foro pelo lesado individual. 26. Responsabilidade e culpa. Prescrição e decadência. 27. A atuação do Ministério Público no processo civil fundado na defesa dos interesses difusos e coletivos, e limites de atuação. Responsabilidade dos membros do Ministério Público. O inquérito civil. Generalidades. Competência e objeto. Instrução. Arquivamento e controle. Efeitos do arquivamento do inquérito civil. Recursos no inquérito civil. Instrumentos de resolução extrajudicial de conflitos de natureza coletiva. Inquérito civil. Termo de ajustamento de conduta (TAC). Fundos. 28. A proteção ao patrimônio cultural e ao patrimônio público e social. Proteção e defesa de bens de valor artístico, estético, histórico, turístico e paisagístico. A competência. A defesa das pessoas portadoras de deficiência. 29. A ação civil pública no Estatuto da Criança e do Adolescente. Da defesa dos investidores no mercado imobiliário. A Defesa da ordem econômica e da economia popular. A defesa das pessoas idosas. A defesa da ordem urbanística. 30. Tutela de outros direitos metaindividuais. Saúde (Lei nº 8.080/1990). Igualdade Racial (Lei nº 12.288/2010). Pessoas portadoras de deficiência (Lei nº 7.853/1989, Lei nº 10.098/2000. Lei nº 10.216/2001 e Decreto nº 6.949/2009). Educação (Lei nº 9.394/1996). Saneamento Básico (Lei nº 11.445/2007, Lei nº 14.026/2020 e Decreto nº 7.217/2010). Idoso (Lei nº 10.741/2003). Patrimônio Público (Lei nº 4.717/1965 e Lei nº 8.429/1992). Mulher (Lei nº 11.340/2006) e Investidor (Lei nº 7.913/1989). População em situação de rua. Política Nacional Judicial de Atenção a Pessoas em Situação de Rua e suas interseccionalidades (Resolução CNJ nº 425/2021). Violência e discriminação em razão de identidade de gênero e orientação sexual. Protocolo para julgamento com perspectiva de gênero (Grupo de Trabalho do CNJ instalado pela Portaria nº 27/2021). População carcerária e em cumprimento de pena ou de medida socioeducativa. A pessoa com deficiência auditiva ou visual em privação de liberdade (Recomendação CNJ nº 81/2020). Direito à assistência e à diversidade religiosa (Recomendação CNJ nº 119/2021). Direitos da população LGBTQIA+ (Resolução CNJ nº 348/2020).'),
  ('Direito da Criança e do Adolescente (ECA)', '1. Aspectos Gerais do Direito da Criança e do Adolescente. A proteção da infância no Brasil. 2. O Direito de ser Criança e Adolescente. Retrospectiva Histórica. A proteção integral. O Princípio do Melhor Interesse da Criança. 3. A Trilogia da Proteção Integral. Convenção Internacional sobre os Direitos da Criança. 4. Responsabilidade Civil. Danos Causados por Crianças e Adolescentes. 5. Direito à Vida e a Proteção ao Nascituro. 6. Direito Fundamental à Convivência Familiar e Comunitária. Parentesco. Poder Familiar. 7. Colocação em Família Substituta: Guarda, Tutela e Adoção. 8. Direito Fundamental à Educação e Cultura. Fundamentos constitucionais e legais. Os direitos infantojuvenis na Lei de Diretrizes e Bases da Educação. 9. O Direito à Profissionalização e a Proteção do Trabalho Urbano e Rural do Adolescente. 10. Direito Fundamental à Saúde da Criança e do Adolescente. 11. A Justiça da Infância e da Juventude. Aspectos Processuais e Procedimentos Especiais. Atuação do Ministério Público. 12. A prevenção geral e especial no Estatuto. Autorização de viagem. Resolução CNJ nº 295 de 13/09/2019. Formas de controle. A ação civil pública. 13. Crimes e Infrações Administrativas contra a Criança e o Adolescente: Código Penal, Estatuto e Legislação Especial. 14. Conselho Tutelar. Conselho de Direitos da Criança e do Adolescente. Fundo da Infância e Adolescência. 15. Direito à educação especial na perspectiva inclusiva. 16. Ato Infracional. Garantias Processuais. Aplicação de Medidas de Proteção e Medidas Socioeducativas. Recomendação CNJ nº 87/2021. Direitos de visita aos adolescentes em cumprimento de medida socioeducativa de internação. Atendimento ao adolescente com transtorno mental e com dependência de álcool ou substância psicoativa. Política Nacional de Atenção Integral à Saúde de Adolescentes em conflito com a Lei (PNAISARI). Resolução CNJ nº 369/2021. 17. Estatuto da Criança e do Adolescente. 18. SINASE (Sistema Nacional de Atendimento Socioeducativo ­ Resolução CONANDA nº 119, de 11.12.06) e Lei nº 12.594, de 18 de janeiro de 2012. 19. Lei Orgânica da Assistência Social - LOAS (Lei nº 8.742/1993, com as alterações da Lei nº 12.435/2011). Política Nacional de Assistência Social (Resolução do Conselho Nacional de Assistência Social nº 145/04 ­). Tipificação Nacional dos Serviços Socioassistenciais (Resolução do Conselho Nacional de Assistência Social nº 109/09). Provimento Corregedoria CNJ nº 118/2021 e suas alterações. Resolução CNJ nº 165/2012 e suas alterações. Recomendação CNJ nº 98/2021. Resolução CONANDA nº 169/2014. 20. Resoluções nº 113, de 19.04.06 e nº 117, de 11.07.06, ambas do Conselho Nacional dos Direitos da Criança e do Adolescente (CONANDA), que dispõem sobre os parâmetros para a institucionalização e fortalecimento do Sistema de Garantia dos Direitos da Criança e do Adolescente. 21. Proteção e direitos das crianças e adolescentes com transtornos mentais. 22. Lei nº 13.431/2017 ­ Sistema de garantia de direitos da criança e do adolescente vítima ou testemunha de violência. Lei nº 14.344/2022 ­ cria mecanismos para a prevenção e o enfrentamento da violência doméstica e familiar contra a criança e o adolescente, nos termos do § 8º do art. 226 e do § 4º do art. 227 da Constituição Federal e das disposições específicas previstas em tratados, convenções ou acordos internacionais de que o Brasil seja parte. 23. Provimento Corregedoria Nacional de Justiça nº 118/2021 (Dispõe sobre as audiências concentradas protetivas nas Varas com competência na área da Infância e Juventude). 24. Resolução CNJ nº 414/2021 (Estabelece diretrizes e quesitos periciais para a realização dos exames de corpo de delito nos casos em que haja indícios de prática de tortura e outros tratamentos cruéis, desumanos ou degradantes, conforme os parâmetros do Protocolo de Istambul, e dá outras providências). 25. Resolução CNJ nº 289/2019 (Dispõe sobre a implantação e funcionamento do Sistema Nacional de Adoção e Acolhimento ­ SNA e dá outras providências). 26. Resolução CNJ nº 165/2012 (Dispõe sobre normas gerais para o atendimento, pelo Poder Judiciário, ao adolescente em conflito com a lei no âmbito na internação provisória e do cumprimento das medidas socioeducativas).'),
  ('Direito Penal', '1. Finalidades do Direito Penal. Teoria Constitucionalista do Delito. Funcionalismo e Imputação Objetiva no Direito Penal. Teoria do Garantismo Penal. 2. Tipicidade Penal. Tipicidade Conglobante. 3. Princípios constitucionais penais. 4. O tempo do crime. A lei penal no tempo e no espaço. 5. Do Crime. Relação de causalidade. Culpabilidade e exculpantes. Do crime consumado, tentado e impossível. Crimes de dano e de perigo. Desistência voluntária e arrependimento eficaz. Arrependimento posterior. Do Crime doloso, culposo e preterdoloso. 6. Erro de tipo. Erro de proibição. Erro sobre a pessoa. Coação irresistível e obediência hierárquica. Causas excludentes da ilicitude. 7. Perdão judicial. Da imputabilidade penal. Da ação e da omissão. 8. Do concurso de pessoas. Do concurso de crimes. 9. Das penas: espécies, cominação, aplicação, função e política criminal. Das penas alternativas e substitutivas. Da suspensão condicional da pena. Do livramento condicional. 10. Efeitos da condenação e da reabilitação. Das medidas de segurança. 11. Da ação penal pública e privada. Da extinção da punibilidade. 12. Dos crimes em espécie do Código Penal: dos crimes contra a pessoa; dos crimes contra o patrimônio; dos crimes contra a propriedade intelectual; dos crimes contra a dignidade sexual; dos crimes contra a família; dos crimes contra a incolumidade pública; dos crimes contra a paz pública; dos crimes contra a administração pública; dos crimes contra a honra; dos crimes contra a liberdade individual; dos crimes contra a fé pública. 13. Dos crimes em espécie previstos em legislação especial: dos crimes de tortura; dos crimes contra a ordem tributária, econômica e relações de consumo; dos crimes do Código de Defesa do Consumidor; dos crimes de lavagem ou ocultação de bens e valores; dos crimes do Código de Trânsito Brasileiro; dos crimes de violência familiar e doméstica contra a mulher; dos crimes contra idosos; dos crimes previstos no Estatuto da Criança e do Adolescente e o menor em conflito com a lei; dos crimes de preconceito racial; dos crimes previstos na Lei de Organizações criminosas; dos crimes de abuso de autoridade; dos crimes ambientais; dos crimes previstos no Estatuto do Desarmamento. Dos crimes de responsabilidade dos prefeitos e vereadores. 14. Das contravenções penais. Dos crimes de menor potencial ofensivo. Juizado Especial Criminal. 15. Lei de Antidrogas e política de redução de danos.'),
  ('Direito Processual Penal', '1. Princípios constitucionais do processo penal. 2. Aplicação da lei processual no tempo, no espaço e em relação às pessoas. 3. Inquérito policial. 4. Ação penal: conceito, condições, pressupostos processuais. Ação penal de iniciativa pública. Titularidade, condições de procedibilidade. Denúncia: forma e conteúdo; recebimento e rejeição. Ação penal de iniciativa privada: Titularidade. Queixa. Renúncia. Perdão. Decadência. Perempção. Extinção da punibilidade. 5. Ação civil ex delicto. 6. Jurisdição e competência. Critérios de determinação e modificação de competência. Incompetência. Conexão e continência. 7. Das questões e processos incidentes. 8. Da prova: conceito, princípios básicos, objeto, meios, espécies, ônus, procedimento probatório, limitações constitucionais das provas, sistemas de apreciação. 9. Sujeitos processuais: do juiz, do Ministério Público, do acusado e defensor, dos assistentes e auxiliares da Justiça. Vítima no processo penal. 10. Da prisão, das medidas cautelares e da liberdade provisória. Disposições gerais. Da prisão em flagrante. Da prisão preventiva. Da prisão domiciliar. Das outras medidas cautelares. Da liberdade provisória, com ou sem fiança. Da prisão temporária. 11. Das medidas assecuratórias. 12. Das citações e intimações. Forma, lugar e tempo dos atos processuais. 13. Processo e procedimento. Pressupostos processuais. Formas procedimentais. Procedimento comum. Instrução criminal. Procedimento ordinário. Procedimento sumário. Procedimento sumaríssimo. Juizados Especiais Criminais. Procedimento relativo ao Tribunal do Júri. Procedimentos especiais, inclusive de leis especiais. 14. Da sentença. Conceito, requisitos, classificação, publicação e intimação. Sentença absolutória: providências e efeitos. Sentença condenatória: fundamentação da pena e efeitos. Efeitos civis da sentença penal. 15. Das nulidades. 16. Dos recursos em geral: princípios, modalidades, recursos em espécie e fungibilidade. 17. Recursos especial e extraordinário. 18. Das ações de impugnação. Da revisão criminal. Do habeas corpus. Do mandado de segurança. Das exceções. Do desaforamento. 19. Aspectos processuais penais das seguintes Leis, com as alterações legislativas que seguiram em relação a elas: Execução Penal (Lei nº 7.210/1984); Juizado especial criminal (Lei nº 9.099/1995); Interceptação telefônica (Lei nº 9.296/1996); Lavagem ou ocultação de bens, direitos e valores (Lei nº 9.613/1998); Proteção a testemunhas (Lei nº 9.807/1999); Organizações criminosas (Lei nº 12.850/2013); Violência doméstica (Lei nº 11.340/2006) e Drogas (Lei nº 11.343/2006). Crimes de responsabilidade de prefeitos e vereadores (Decreto-Lei nº 201/1967).'),
  ('Direito Constitucional', '1. Constituição: fontes; conceito; objeto; classificações; estrutura. Supremacia da Constituição. Aplicabilidade e interpretação das normas constitucionais. Vigência e eficácia das normas constitucionais. 2. Poder constituinte. Judicialização e Ativismo judicial. 3. Controle de constitucionalidade. Sistema. Ação direta de inconstitucionalidade. Ação declaratória de constitucionalidade. Arguição de descumprimento de preceito fundamental. Ação direta de inconstitucionalidade por omissão. Efeitos da decisão no controle abstrato. A fiscalização abstrata no plano estadual. A Fiscalização incidental. Ação direta interventiva. 4. Controle de constitucionalidade das leis municipais. A ação direta de inconstitucionalidade no âmbito estadual e o problema da norma repetida. Norma Constitucional Inconstitucional. O fenômeno da recepção da legislação em vigor pela nova Ordem Constitucional. Modulação dos efeitos da declaração de inconstitucionalidade. Mutação constitucional. Ação direta interventiva. 5. Estado Federal. Princípios fundamentais da Constituição Federal. Jurisdição constitucional e processo constitucional. Coisa julgada e processo constitucional. 6. Direitos e garantias fundamentais. Dos direitos e deveres individuais e coletivos. Tratados e convenções sobre direitos humanos. Convenção Americana sobre Direitos Humanos (Pacto de San José da Costa Rica, de 22 de novembro de 1969, promulgado pelo Decreto nº 678/1992) e Pacto Internacional sobre Direitos Civis e Políticos (de 16 de dezembro de 1966, promulgado pelo Decreto nº 592/1992). A razoável duração do processo. Direitos sociais. Direitos políticos. Partidos políticos. Direitos de nacionalidade. Tutela constitucional dos direitos e das liberdades. Mandado de segurança, individual e coletivo. Mandado de Injunção. Habeas corpus. Habeas data. Ação popular. Ação civil pública. 7. Organização do Estado Brasileiro: Organização político-administrativa; União; Estados federados; Municípios; Distrito Federal e Territórios. Repartição de competências. Bens públicos. 8. Intervenção nos Estados e nos Municípios. Administração pública: Disposições gerais; Servidores públicos. 9. Organização dos Poderes na Constituição Federal. Poder Executivo. Presidente e Vice-Presidente da República: Atribuições e Responsabilidades. Poder Legislativo. Órgãos, funcionamento e competências. Prerrogativas e impedimentos no exercício do mandato parlamentar. Processo legislativo. Fiscalização contábil, financeira e orçamentária. Tribunal de Contas da União. Poder Judiciário. Supremo Tribunal Federal. Competência. Recurso Extraordinário. Repercussão Geral. Súmula vinculante. Superior Tribunal de Justiça. Competência. Recurso Especial. 10. Organização dos Poderes na Constituição Federal. Poder Judiciário. Conselho Nacional de Justiça. Dos Tribunais Regionais Federais e dos Juízes Federais. Dos Tribunais e Juízes Eleitorais. Dos Tribunais e Juízes dos Estados. Direitos e Deveres da Magistratura. Garantias da magistratura. Lei Orgânica da Magistratura Nacional (LOMAN) e Código de Ética da Magistratura Nacional (aprovado pelo CNJ). Funções essenciais à Justiça. Do Ministério Público. Do Conselho Nacional do Ministério Público. Da Advocacia Pública. Da Advocacia e da Defensoria Pública. 11. Constituição do Estado de Goiás. Poder Executivo do Estado de Goiás. Atribuições e responsabilidades do Governador e do Prefeito. 12. Constituição do Estado de Goiás. Poder Legislativo do Estado de Goiás. Prerrogativas e impedimentos de deputados estaduais e dos vereadores. Processo legislativo estadual. Fiscalização contábil, financeira e orçamentária. Tribunal de Contas do Estado. Tribunal de Contas dos Municípios. 13. Constituição do Estado de Goiás. Poder Judiciário do Estado de Goiás. Órgãos do Poder Judiciário Estadual. Atribuições, competências e prerrogativas do Poder Judiciário na Constituição Estadual. Da declaração de inconstitucionalidade e da ação direta de inconstitucionalidade na Constituição Estadual. 14. Ordem econômica e financeira. Princípios gerais da atividade econômica. Da Política Urbana. Tributação e orçamento. Do Sistema Tributário Nacional. Das Finanças Públicas. 15. Da Defesa do Estado e das Instituições Democráticas. Da Ordem Social. Emenda Constitucional nº 45/2004 ­ Reforma do Judiciário. Emendas Constitucionais. Administração pública e o controle de constitucionalidade.'),
  ('Direito Eleitoral', '1. Direito eleitoral. Conceito. Fundamentos. Fontes e princípios. Interpretação. Aplicação subsidiária do Código de Processo Civil. 2. Dos órgãos da Justiça Eleitoral. Do Tribunal Superior Eleitoral. Dos Tribunais Regionais Eleitorais. Dos Juízes Eleitorais. Das Juntas Eleitorais. Composição e atribuições. Do Ministério Público Eleitoral. 3. Do Alistamento Eleitoral: ato e efeitos da inscrição, transferência e encerramento. Cancelamento e exclusão do eleitor. Do domicílio eleitoral. 4. Direitos políticos. Perda. Suspensão. Sufrágio universal. Voto. Característica do voto. Do sistema eleitoral: sistema majoritário e sistema proporcional. 5. Das coligações. Das convenções para a escolha de candidatos. Do registro de candidatos. Elegibilidade e inelegibilidade. Impugnação de registro de candidatos. Fundo Especial de Financiamento de Campanha. Da arrecadação e da aplicação de recursos nas campanhas eleitorais, Da prestação de contas. 6. Da votação: atos preparatórios, início e encerramento. Dos lugares de votação, das seções eleitorais e das mesas receptoras. Da polícia e da fiscalização perante as mesas receptoras. Da apuração. Do Sistema Eletrônico de Votação e da Totalização dos Votos. 7. Das impugnações perante as juntas eleitorais. Da proclamação e da diplomação dos eleitos. Recurso contra expedição de diploma. 8. Dos recursos eleitorais: pressupostos de admissibilidade. Efeitos e prazos. Recursos perante as Juntas e Juízos Eleitorais e Tribunais Regionais. 9. Dos partidos políticos. Registro e funcionamento partidário. Criação, fusão, incorporação e extinção dos partidos políticos. Da filiação partidária. Da fidelidade e da disciplina partidárias. Das finanças e contabilidade dos partidos. Fundo partidário. Prestação de contas. Aspectos constitucionais, legais e éticos dos partidos políticos. 10. Das pesquisas e testes pré-eleitorais. Da propaganda eleitoral em geral. Da propaganda eleitoral na imprensa. Da propaganda eleitoral no rádio e na televisão. Propaganda na internet. Do direito de resposta. Das condutas vedadas aos agentes públicos em campanhas eleitorais. 11. Da ação de impugnação de mandato eletivo. Da investigação judicial eleitoral. Do mandado de segurança. 12. Dos crimes eleitorais. Conceito, natureza e classificação. Tipos previstos na legislação eleitoral. 13. Do processo penal eleitoral. Investigação criminal eleitoral. Ação penal. Competência em matéria criminal eleitoral. Rito processual penal eleitoral. Invalidação e nulidade de atos eleitorais. Recursos. 14. Lei Complementar nº 64, de 18 de maio de 1990. 15. Lei nº 9.096, de 19 de setembro de 1995. 16. Lei nº 9.504, de 30 de setembro de 1997. 17. Lei Complementar nº 86/1996.'),
  ('Direito Empresarial', '1. Do Direito de Empresa. Do Empresário. Da caracterização e da inscrição. Da capacidade. 2. Da Sociedade. Disposições gerais. Da sociedade não personificada. Da sociedade em comum. Da sociedade em conta de participação. Da sociedade personificada. Da sociedade simples. Da sociedade em nome coletivo. Da sociedade em comandita simples. Da sociedade limitada. Da sociedade anônima. Da sociedade em comandita por ações. Da sociedade cooperativa. Das sociedades coligadas. 3. Da liquidação da sociedade. Da transformação, da incorporação, da fusão e da cisão das sociedades. Da sociedade dependente de autorização. 4. Do Estabelecimento. Disposições gerais. 5. Dos Institutos Complementares: Do registro. Do nome empresarial. Dos prepostos. Da escrituração. Da Propriedade Industrial e Propriedade Intelectual, da Marca e Patente, Patente Pipeline, do Modelo de Utilidade, do Desenho Industrial. 6. Do registro. Do nome empresarial. Dos prepostos. Da escrituração. 7. Da Recuperação Judicial, Extrajudicial e a Falência do Empresário e da Sociedade Empresária (Lei nº 11.101/2005 e todas as alterações posteriores). 8. Da Microempresa e da Empresa de Pequeno Porte (Lei Complementar nº 123/2006). 9. Da Letra de Câmbio e da Nota Promissória (Decreto nº 2.044/1908, Decreto nº 57.663/1966). 10. Do Cheque (Lei nº 7.357/1985). Da Duplicata (Lei nº 5.474/1968). Dos Atos Cambiários e dos Contratos Empresariais. 11. Do Protesto de Títulos (Lei nº 9.492/1997). 12. Dos Títulos de Crédito Comercial (Lei nº 6.840/1980). Dos Títulos de Crédito Industrial. 13. Dos Títulos de Crédito Rural (Decreto-Lei nº 167/1967 e Lei nº 11.076/2004). Cédulas de crédito bancário (Lei nº 10.931/2004). 14. Das Sociedades por Ações (Lei nº 6.404/1976). 15. Da Intervenção e Liquidação Extrajudicial de Instituições Financeiras (Lei nº 6.024/1974).'),
  ('Direito Tributário', '1. O Estado e o poder de tributar. Fundamentos da imposição tributária, suas limitações no nosso ordenamento. Imunidade, isenção, alíquota zero, diferimento, incidência e não incidência. Espécies de imunidades previstas na Constituição. 2. Sistema Tributário Nacional. Princípios gerais. Princípios constitucionais tributários. Competência legislativa e Competência Tributária. Limitações da competência tributária. Discriminação, repartição, destinação e vinculação constitucional da receita tributária. Fundos de participação. 3. Fontes do direito tributário. Hierarquia das normas. Vigência e aplicação da legislação tributária no tempo e no espaço. Legislação tributária. Conceitos. Lei ordinária e lei complementar; Lei Delegada; Decretos Legislativos; Resoluções do Senado; Atos Normativos de Autoridade Administrativa; Decretos e Despachos Normativos do Executivo; Resoluções Administrativas; Portarias; Decisões Administrativas e Consultas. Matérias reservadas à previsão por Lei Complementar. Medida provisória. Tratados e convenções internacionais. Convênios do CONFAZ. 4. Regras de vigência, aplicação e integração. Interpretação e integração da legislação tributária. 5. Obrigação tributária. Obrigação principal e acessória. Fato Gerador: ocorrência, aspectos materiais, temporal e espacial. Elementos valorativos: base de cálculo e alíquota. Efeitos, consequências, validade e invalidade dos atos jurídicos. Sujeitos ativo e passivo da obrigação tributária: contribuinte, responsável e substituto. Solidariedade. A imposição tributária e as convenções particulares. Capacidade tributária. Domicílio tributário. Preferência. Fraude à execução. Decretação de indisponibilidade no curso do processo executivo: requisitos e procedimento. 6. Decadência e Prescrição em matéria tributária. Prescrição intercorrente judicial e administrativa. 7. Responsabilidade tributária: sucessores, terceiros, responsabilidade nas infrações, responsabilidade dos diretores e gerentes das pessoas jurídicas de direito privado por dívidas sociais. Responsabilidade supletiva. Desconsideração da personalidade jurídica. Substituição tributária. Pagamento e pagamento indevido: Compensação e Repetição de Indébito. Atualização do crédito tributário. 8. Crédito tributário: constituição, lançamento, natureza jurídica. Caráter vinculado da atividade de lançamento, efeitos e modalidades. Suspensão, extinção e exclusão do crédito tributário. Garantias e privilégios do crédito tributário. 9. Tributos. Conceito. Natureza jurídica. Classificação: impostos, taxas, contribuições de melhoria, empréstimos compulsórios e contribuições sociais. Contribuições: espécies e natureza jurídica. Preços públicos, tarifas e taxas: distinção. Pedágio. Extrafiscalidade e parafiscalidade. Tributação dos ganhos de capital: tendências do sistema e seus fundamentos. Tributação sobre o valor agregado: tendências do sistema e seus fundamentos. 10. Tributos dos estados e municípios. Impostos estaduais: ICMS, IPVA, ITCMD. Impostos municipais: ISS, ITBI, IPTU. 11. Administração tributária: fiscalização, sigilo, auxílio da força pública, excesso de exação. Capacidade tributária ativa: fiscalização e arrecadação de tributos. Dívida ativa: inscrição, presunção de certeza e de liquidez e consectários. Dívida ativa de origem tributária e não tributária. Certidão negativa, positiva e positiva com efeito de negativa. 12. Processo administrativo fiscal: consulta, contencioso administrativo, execução administrativa. Processo judicial tributário. Ações de iniciativa do fisco: execução fiscal, cautelar fiscal. Ações de iniciativa do contribuinte: anulatória do débito fiscal, embargos à execução fiscal e seus efeitos, exceção de pré- executividade, declaratória, de consignação em pagamento, de repetição de indébito, mandado de segurança. 13. Tributação internacional. Acordos para evitar a dupla tributação. Aspectos tributários da OMC, MERCOSUL, ALADI e ALCA. Incentivos fiscais. Legislação. Análise crítica do sistema e de seus reflexos no desenvolvimento do País. Evasão e elisão tributárias. 14. Ilícito tributário. Ilícito e sanção. Ilícito administrativo tributário. Ilícito penal tributário: crimes contra a ordem tributária no Código Penal e na legislação penal específica. Sanção administrativa e sanção penal. Consequências do inadimplemento. Responsabilidade penal. Sanções pessoais e patrimoniais. Fraude à lei e abuso de direito. Denúncia espontânea. 15. Sistema integrado de pagamento de impostos e contribuições das microempresas e das empresas de pequeno porte (SIMPLES). 16. Direito financeiro. Atividade financeira do Estado: fundamentos financeiros, econômicos e jurídicos. Sede constitucional e normas constitucionais de Direito Financeiro. Plano Plurianual. Lei de Diretrizes Orçamentárias. Lei Orçamentária Anual. Lei nº 4.320/1964 e suas alterações. Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000.'),
  ('Direito Financeiro', '1. O Estado e o poder de tributar. Fundamentos da imposição tributária, suas limitações no nosso ordenamento. Imunidade, isenção, alíquota zero, diferimento, incidência e não incidência. Espécies de imunidades previstas na Constituição. 2. Sistema Tributário Nacional. Princípios gerais. Princípios constitucionais tributários. Competência legislativa e Competência Tributária. Limitações da competência tributária. Discriminação, repartição, destinação e vinculação constitucional da receita tributária. Fundos de participação. 3. Fontes do direito tributário. Hierarquia das normas. Vigência e aplicação da legislação tributária no tempo e no espaço. Legislação tributária. Conceitos. Lei ordinária e lei complementar; Lei Delegada; Decretos Legislativos; Resoluções do Senado; Atos Normativos de Autoridade Administrativa; Decretos e Despachos Normativos do Executivo; Resoluções Administrativas; Portarias; Decisões Administrativas e Consultas. Matérias reservadas à previsão por Lei Complementar. Medida provisória. Tratados e convenções internacionais. Convênios do CONFAZ. 4. Regras de vigência, aplicação e integração. Interpretação e integração da legislação tributária. 5. Obrigação tributária. Obrigação principal e acessória. Fato Gerador: ocorrência, aspectos materiais, temporal e espacial. Elementos valorativos: base de cálculo e alíquota. Efeitos, consequências, validade e invalidade dos atos jurídicos. Sujeitos ativo e passivo da obrigação tributária: contribuinte, responsável e substituto. Solidariedade. A imposição tributária e as convenções particulares. Capacidade tributária. Domicílio tributário. Preferência. Fraude à execução. Decretação de indisponibilidade no curso do processo executivo: requisitos e procedimento. 6. Decadência e Prescrição em matéria tributária. Prescrição intercorrente judicial e administrativa. 7. Responsabilidade tributária: sucessores, terceiros, responsabilidade nas infrações, responsabilidade dos diretores e gerentes das pessoas jurídicas de direito privado por dívidas sociais. Responsabilidade supletiva. Desconsideração da personalidade jurídica. Substituição tributária. Pagamento e pagamento indevido: Compensação e Repetição de Indébito. Atualização do crédito tributário. 8. Crédito tributário: constituição, lançamento, natureza jurídica. Caráter vinculado da atividade de lançamento, efeitos e modalidades. Suspensão, extinção e exclusão do crédito tributário. Garantias e privilégios do crédito tributário. 9. Tributos. Conceito. Natureza jurídica. Classificação: impostos, taxas, contribuições de melhoria, empréstimos compulsórios e contribuições sociais. Contribuições: espécies e natureza jurídica. Preços públicos, tarifas e taxas: distinção. Pedágio. Extrafiscalidade e parafiscalidade. Tributação dos ganhos de capital: tendências do sistema e seus fundamentos. Tributação sobre o valor agregado: tendências do sistema e seus fundamentos. 10. Tributos dos estados e municípios. Impostos estaduais: ICMS, IPVA, ITCMD. Impostos municipais: ISS, ITBI, IPTU. 11. Administração tributária: fiscalização, sigilo, auxílio da força pública, excesso de exação. Capacidade tributária ativa: fiscalização e arrecadação de tributos. Dívida ativa: inscrição, presunção de certeza e de liquidez e consectários. Dívida ativa de origem tributária e não tributária. Certidão negativa, positiva e positiva com efeito de negativa. 12. Processo administrativo fiscal: consulta, contencioso administrativo, execução administrativa. Processo judicial tributário. Ações de iniciativa do fisco: execução fiscal, cautelar fiscal. Ações de iniciativa do contribuinte: anulatória do débito fiscal, embargos à execução fiscal e seus efeitos, exceção de pré- executividade, declaratória, de consignação em pagamento, de repetição de indébito, mandado de segurança. 13. Tributação internacional. Acordos para evitar a dupla tributação. Aspectos tributários da OMC, MERCOSUL, ALADI e ALCA. Incentivos fiscais. Legislação. Análise crítica do sistema e de seus reflexos no desenvolvimento do País. Evasão e elisão tributárias. 14. Ilícito tributário. Ilícito e sanção. Ilícito administrativo tributário. Ilícito penal tributário: crimes contra a ordem tributária no Código Penal e na legislação penal específica. Sanção administrativa e sanção penal. Consequências do inadimplemento. Responsabilidade penal. Sanções pessoais e patrimoniais. Fraude à lei e abuso de direito. Denúncia espontânea. 15. Sistema integrado de pagamento de impostos e contribuições das microempresas e das empresas de pequeno porte (SIMPLES). 16. Direito financeiro. Atividade financeira do Estado: fundamentos financeiros, econômicos e jurídicos. Sede constitucional e normas constitucionais de Direito Financeiro. Plano Plurianual. Lei de Diretrizes Orçamentárias. Lei Orçamentária Anual. Lei nº 4.320/1964 e suas alterações. Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000.'),
  ('Direito Ambiental', '1. Meio Ambiente. Teoria Geral do Direito ambiental. Conceito. Natureza. Fontes e Princípios. Ética Ambiental. Meio Ambiente na Constituição Federal. Fundamento constitucional. Ecologia ou Antropologia. Estado Constitucional Ecológico. A Ética e o ambiente natural, cultural e artificial. A ética ambiental e o Estatuto da Cidade. Jurisprudência das Câmaras Reservadas ao Meio Ambiente do Tribunal de Justiça. 2. Política ambiental constitucional. Deveres ambientais. Deveres ecológicos e regulamentação da atividade econômica na Constituição Federal. 3. Direito Ambiental Constitucional. Competência legislativa em matéria ambiental. Competências legislativas exclusivas e concorrentes. Competência material na defesa do meio ambiente. 4. Bens Ambientais. Águas, cavidades naturais subterrâneas. Energia. Espaços territoriais protegidos e seus componentes: Fauna, Flora, Florestas, Ilhas, Paisagem, Mar Territorial, Praias fluviais, Praias marítimas. Recursos naturais da plataforma continental. Recursos da zona econômica exclusiva. Sítios arqueológicos e pré-históricos. Terrenos de marinha e seus acrescidos. Terrenos marginais. 5. Política Nacional do Meio Ambiente. Princípios da PNMA. Objeto. Finalidade. Instrumentos da PNMA. 6. SISNAMA ­ Sistema Nacional do Meio Ambiente. Objeto. Órgãos integrantes. Órgão Superior. Conselho de Governo. 7. Órgão Consultivo e Deliberativo (CONAMA). Órgão Central ­ Ministério do Meio-Ambiente. Recursos Hídricos e Amazônia legal. Órgão executor ­ IBAMA. Órgãos Setoriais. Órgãos Seccionais e órgãos locais. Fundo Nacional do Meio Ambiente (FNMA). Licenciamento Ambiental. Sistema de Licenciamento. 8. Tipos de Licença (Licença Prévia, Licença de Instalação e Licença de Operação). Outorgas das Licenças. Licença Ambiental para fins específicos. Função e Natureza Jurídica do Estudo de Impacto Ambiental. Licenciamento ambiental estadual (Lei Estadual nº 20.694/2019). 9. Conceito jurídico de impacto ambiental. Exigência Constitucional dos Estudos de Impacto Ambiental. O EIA na legislação nacional. Competência Legislativa sobre o EIA. Competência para exigir o EIA. Estados e Municípios. Competência do CONAMA para estabelecer as diretrizes sobre o EIA. Normas Gerais. Conteúdo do EIA. RIMA. Audiência Pública. As licitações e o EIA. 10. Conceito de Zoneamento Ambiental. Finalidade. Natureza jurídica. Zoneamento Ambiental Urbano. Zonas de Uso Industrial ­ ZUI. Zonas de Uso Estritamente Industrial ­ ZUEI. Zona de Uso Predominantemente Industrial ­ ZUPI. Zona de Uso Diversificado ­ ZUD. Zoneamento Ambiental Agrícola e Zoneamento Ambiental Costeiro. Zoneamento Ecológico-Econômico. 11. O Dano Ambiental. Apuração do Dano Ambiental. Reparação do Dano Ambiental. Responsabilidade Administrativa, Civil e Penal por danos ao Meio Ambiente. Infrações Administrativas Ambientais. Sanções para as infrações administrativas ambientais. O Poder de Polícia e Direito Ambiental. 12. Meios processuais para a defesa ambiental. Ação Popular. Ação Civil Pública. Competência para o processamento e julgamento das ações civis públicas por danos ao meio ambiente. Legitimidade ativa. Mandado de Segurança Individual e Coletivo. Mandado de Injunção. Ação Direta de Inconstitucionalidade. Desapropriação. Tombamento. A tutela inibitória em matéria de proteção ao meio ambiente. A tutela de urgência e de evidência no direito ambiental. O acesso coletivo à tutela jurisdicional em matéria ambiental. Intervenção de Terceiros stricto e lato sensu. Recursos. 13. Crimes contra o meio ambiente. Responsabilidade penal ambiental. Responsabilidade penal da pessoa jurídica. Ação e processo penal. Competência para julgar os crimes contra o meio ambiente. Crimes contra a fauna. Crimes contra a flora. Crimes contra o ordenamento urbano e patrimônio cultural. Crimes de poluição. 14. O Direito Ambiental Internacional. Conceito. Fontes do Direito ambiental internacional. Princípios gerais do direito ambiental internacional. MERCOSUL e Direito Ambiental Internacional. Procedimentos administrativos de prevenção de dano ambiental nacional transfronteiriço. As Organizações Não Governamentais. ONGs. 15. Espaços territoriais especialmente protegidos. SNUC ­ Sistema Nacional de Unidades de Conservação da Natureza. Código Florestal. Lei da Mata Atlântica. Proteção do Cerrado. 16. Política Nacional de Recursos Hídricos. Política Nacional de Saneamento Básico. Política Nacional de Resíduos Sólidos. Política Estadual de Recursos Hídricos (Lei Estadual nº 13.123/1997). 17. Conceito de Poluição. Poluição das águas. Poluição Atmosférica. Poluição por resíduos sólidos. Poluição por rejeitos perigosos. Poluição por agrotóxicos. Poluição sonora. Áreas de Preservação Permanente e Unidades de Conservação: Fundamento Constitucional. Política Estadual de Mudanças Climáticas (Lei Estadual nº 16.497/2009). Pagamento por Serviços Ambientais (Decreto Estadual nº 9.130/2017). Mudança do Clima e Mercado de Carbono.'),
  ('Direito Administrativo', '1. As funções do Estado. Origem do Direito Administrativo. O regime jurídico-administrativo. Conteúdo do regime jurídico-administrativo. Aplicação do regime jurídico administrativo a entidades da Administração Indireta, entidades de colaboração e particulares. 2. Princípios Constitucionais do Direito Administrativo. Restrições ao princípio da legalidade. Princípios reconhecidos em legislação infraconstitucional, pela doutrina e pela jurisprudência. Interpretação do direito administrativo. Normas sobre interpretação do direito público na Lei de Introdução ao Direito Brasileiro. Controle sistemático das relações administrativas. 3. Ato administrativo: conceito, elementos, atributos, classificação, espécies. Perfeição, validade e eficácia do ato administrativo. Invalidade, nulidade, anulação, cassação, caducidade, convalidação e revogação. Principais espécies. Controle de mérito e de legalidade dos atos administrativos. Controle sistemático dos atos administrativos. 4. Servidores Públicos. Agentes Públicos. Classificação. Normas relativas à remuneração dos servidores e de agentes públicos. Regime dos servidores públicos e titulares de cargos públicos na Constituição Federal e na Constituição do Estado de Goiás. Cargo, emprego e função pública. Provimento, vacância, remoção, redistribuição e substituição. Provimento. Nomeação. Concurso Público. Posse e exercício. Estabilidade. Transferência. Readaptação. Reversão. Reintegração. Recondução. Disponibilidade. Aproveitamento. Vacância. Remoção. Redistribuição. Substituição. 5. Direitos e vantagens dos servidores públicos. Deveres e responsabilidades dos servidores públicos. Do regime disciplinar. O funcionário Público Civil. Da Seguridade social do servidor: aposentadoria e pensões; aposentadoria de magistrado, membros do Ministério Público e do Tribunal de Contas; aposentadoria voluntária, aposentadoria compulsória. Normas relativas à remuneração dos servidores e de agentes políticos. Lei Complementar nº 35/1979 (Lei Orgânica da Magistratura Nacional) e alterações. Lei Estadual nº 20.756/2020 (Estatuto dos Servidores Públicos Civis do Estado de Goiás) e alterações. Lei Complementar Estadual nº 161/2020 (Regime Próprio de Previdência Social do Estado de Goiás) e alterações. 6. Improbidade administrativa: Lei Federal nº 8.429/1992. Agentes do polo ativo e passivo. Atos de improbidade. Da ação de improbidade administrativa. Das penas. Enriquecimento ilícito. Prejuízo ao erário. Princípios. Penas. Procedimento e prescrição. Lei de Responsabilidade Fiscal - Lei Complementar nº 101/2000. Lei de Acesso à Informação - Lei Federal nº 12.527/2011. Lei Anticorrupção - Lei Federal nº 12.846/2013. 7. Controles da Administração Pública: Controle administrativo; Controle legislativo ou político; Controle judicial. Discricionariedade administrativa e controle judicial. Controle interno e controle externo. Controle pelo Tribunal de Contas. Domínio público. Controle sistemático das delegações de serviços públicos. 8. Domínio Público. Bens públicos. Regime jurídico. Classificação, Administração e Utilização. Alienação. Tratamento do tema no Estatuto da Cidade (Lei Federal nº 10.257/2001). 9. Licitação: Princípios, Obrigatoriedade, Dispensa e Exigibilidade, Procedimentos e Modalidades. Pregão presencial e eletrônico. Fases da licitação. Habilitação. Julgamento. Homologação e adjudicação. Recursos administrativos. Crimes. Licitação e mandado de segurança. Regime Diferenciado de Contratações Públicas. Registro de preços. 10. Contrato administrativo. Espécies. Conceito. Características. Prerrogativas da Administração. Formalização. Execução e inexecução. A cláusula rebus sic stantibus. A Teoria da Imprevisão. As cláusulas de reajuste de preços. Obrigações do Estado derivadas de contratos inválidos ou inexistentes. Rescisão e anulação. 11. Convênios e Consórcios. Concessões e Permissões de serviços públicos. Forma e condições da outorga do serviço em concessão. O Prazo nas concessões e sua prorrogação. Poderes do Concedente. Os Direitos do concessionário. Regime tarifário e sua revisão. Os Direitos dos usuários. Formas de extinção da concessão e seus efeitos jurídicos. A reversão dos Bens. Responsabilidades civis do concessionário e do Poder concedente. Permissão. Parcerias Público-Privadas. 12. Parcerias com o terceiro setor. Convênios e outras espécies de ajustes colaborativos. Organizações sociais. OSCIP''s. Organizações da Sociedade Civil. 13. Infrações e Sanções Administrativas. Conceito. Sujeito infrator. Excludentes da Infração. Princípios. Dever de sancionar. Processo administrativo. Conceito. Processo ou procedimento administrativo. Princípios do processo administrativo. Instauração do processo administrativo e fases do processo. A sindicância. Os sujeitos da relação processual administrativa. Direitos e deveres das partes. Competência. Instrução do processo administrativo. Decisão do Processo Administrativo: estrutura, tipologia. Recurso Administrativo e seus efeitos. Coisa julgada administrativa. Da revisão administrativa. Da prescrição e da decadência. 14. Poder de polícia: conceito. Intervenção do Estado na propriedade. Função social da propriedade. Desapropriação. Conceito. Requisitos. Bens suscetíveis de desapropriação: Competências relacionadas à desapropriação. Espécies de desapropriação Indenização e consectários legais. Caducidade da desapropriação. Imissão na posse do imóvel desapropriado. Direito de extensão. Desapropriação indireta. Retrocessão. Controle da desapropriação. Servidão administrativa. Tombamento. Requisição. Ocupação provisória. Limitação administrativa. Direito de construir e seu exercício. Loteamento e zoneamento. 15. Responsabilidade civil do Estado: evolução das teorias. Reparação do dano. Responsabilidade objetiva e subjetiva. Caracterização. Causas de exclusão e mitigação. Prescrição e decadência. Responsabilidades dos contratados e delegatários de serviços públicos. Procedimento administrativo e judicial. Direito de regresso. 16. Organização administrativa: noções gerais. Administração direta e indireta, centralizada e descentralizada. Autarquias. Autarquias comuns e especiais. Agências reguladoras e agências executivas. Fundações Públicas, Empresas Públicas e Sociedades de Economia Mista. Consórcios Públicos. Tutela dos entes da Administração Indireta. Entidades de colaboração e seu regime jurídico.'),
  ('Formação Humanística', '1. Organização Judiciária do Estado de Goiás: Código de Organização Judiciária do Estado de Goiás e alterações (Lei Estadual nº 21.868/2022). Regimento de Custas e Emolumentos da Justiça do Estado de Goiás (Lei Estadual nº 14.376/2002). Regimento Interno do Tribunal de Justiça do Estado de Goiás (Resolução nº 170, de 12 de novembro de 2021). Regimento Interno das Turmas Recursais e da Turma de Uniformização do Sistema dos Juizados Especiais do Estado de Goiás (Resolução TJGO n° 225/2023). Juízo 100% Digital (Resolução CNJ nº 345/2020 e alterações). Balcão virtual (Resolução CNJ nº 372/2021 e alterações). Núcleos de Justiça 4.0 (Resolução CNJ nº 385/2021 e Resolução CNJ nº 398/2021). 2. Sociologia do Direito. Introdução à sociologia da administração judiciária. Aspectos gerenciais da atividade judiciária (administração e economia). Gestão. Gestão de pessoas. Relações sociais e relações jurídicas. Controle social e o Direito. Transformações sociais e Direito. Direito, Comunicação Social e opinião pública. Conflitos sociais e mecanismos de resolução. Sistemas não judiciais de composição de litígios. 3. Psicologia Judiciária. Psicologia e Comunicação: relacionamento interpessoal, relacionamento do magistrado com a sociedade e a mídia. Problemas atuais da psicologia com reflexos no direito: assédio moral e assédio sexual. Teoria do conflito e os mecanismos autocompositivos. Técnicas de negociação e mediação. Procedimentos, posturas, condutas e mecanismos aptos a obter a solução conciliada dos conflitos. O processo psicológico e a obtenção da verdade judicial. O comportamento de partes e testemunhas. 4. Ética e Estatuto Jurídico da Magistratura Nacional. Regime Jurídico da Magistratura Nacional: carreira, ingresso, promoções, remoções. Direitos e deveres funcionais da magistratura. Integridade pessoal e profissional do juiz. Dignidade, honra e decoro. Diligência e dedicação. Conhecimento e Capacitação. Cortesia e Prudência do Juiz. Ilícitos éticos. Sanções. Lugar da ética na função judicial e na vida particular do juiz. O papel da cordialidade na prestação jurisdicional. Código de Ética da Magistratura Nacional. Sistemas de controle interno do Poder Judiciário: Corregedorias, Ouvidorias, Conselhos Superiores e Conselho Nacional de Justiça. Responsabilidade administrativa, civil e criminal dos magistrados. Administração judicial. Planejamento estratégico. Modernização da gestão. 5. Filosofia do Direito. O conceito de Justiça. Sentido lato de Justiça, como valor universal. Sentido estrito de Justiça, como valor jurídico-político. Divergências sobre o conteúdo do conceito. O conceito de Direito. Equidade. Direito e Moral. A interpretação do Direito. A superação dos métodos de interpretação mediante puro raciocínio lógico-dedutivo. O método de interpretação pela lógica do razoável. Hermenêutica jurídica. 6. Teoria Geral do Direito e da Política. Direito objetivo e direito subjetivo. Fontes do Direito objetivo. Princípios gerais de Direito. Jurisprudência. Súmula vinculante. Eficácia da lei no tempo. Conflito de normas jurídicas no tempo e o Direito brasileiro: Direito Penal, Direito Civil, Direito Constitucional e Direito do Trabalho. O conceito de Política. Política e Direito. Ideologias. A Declaração Universal dos Direitos do Homem (ONU). Agenda 2030 e os 17 Objetivos de Desenvolvimento Sustentável. Gênero e Patriarcado. Gênero e Raça. Discriminação e Desigualdades de Gênero ­ questões centrais. Protocolo de julgamento com perspectiva de gênero. 7. Direito Digital. 4ª Revolução industrial. Transformação Digital no Poder Judiciário. Tecnologia no contexto jurídico. Automação do processo. Inteligência Artificial e Direito. Audiências virtuais. Cortes remotas. Ciência de dados e Jurimetria. Resoluções do CNJ sobre inovações tecnológicas no Judiciário. Persecução Penal e novas tecnologias. Crimes virtuais e cibersegurança. Deepweb e Darkweb. Provas digitais. Criptomoedas e Lavagem de dinheiro. Noções gerais de contratos Inteligentes, Blockchain e Algoritmos. LGPD e proteção de dados pessoais. 8. Pragmatismo, Análise Econômica do Direito e Economia Comportamental. Função judicial e pragmatismo. Antifundacionalismo. Contextualismo. Consequencialismo. Racionalismo e Empirismo. Dialética. Utilitarismo. Análise econômica do direito. Conceitos fundamentais. Racionalidade econômica. Eficiência processual. Métodos adequados de resolução de conflitos e acesso à Justiça. Demandas frívolas e de valor esperado negativo. Precedentes, estabilidade da jurisprudência e segurança jurídica. Coisa Julgada. Economia comportamental. Heurística e vieses cognitivos. A percepção de Justiça. Processo cognitivo de tomada de decisão. Governança corporativa e Compliance no Brasil. Mecanismos de Combate às organizações criminosas e Lavagem de Dinheiro. Whistleblower. 9. Direito da Antidiscriminação. Conceitos Fundamentais do Direito da Antidiscriminação. Modalidades de Discriminação. Legislação antidiscriminação nacional e internacional. Conceitos Fundamentais do Racismo, Sexismo, Intolerância Religiosa, LGBTQIA+fobia. Ações Afirmativas. Direitos dos Povos indígenas e das comunidades tradicionais.'),
  ('Direitos Humanos', '1. Teoria Geral dos Direitos Humanos. 2. Sistema global de proteção dos direitos humanos. 3. Sistema regional interamericano de proteção dos direitos humanos. 4. Controle de convencionalidade. 5. A relação entre o direito internacional dos direitos humanos e o direito brasileiro. 6. Os direitos humanos na Constituição Federal de 1988. 7. A jurisprudência do Supremo Tribunal Federal em matéria de direitos humanos.')
) as v(materia, texto)
join public.editais_catalog e on e.slug = 'tj-go-juiz-substituto'
join public.subjects_catalog s on s.name = v.materia
on conflict (edital_catalog_id, subject_catalog_id) do update
  set texto = excluded.texto, fonte_url = excluded.fonte_url, conferido_em = excluded.conferido_em;

do $$
declare v int;
begin
  select count(*) into v from public.edital_programas ep
  join public.editais_catalog e on e.id = ep.edital_catalog_id
  where e.slug = 'tj-go-juiz-substituto';
  if v <> 15 then raise exception 'esperado 15 linhas de programa, achei %', v; end if;
end $$;
